const cwReviewTypeDescriptions={
 'Standard Performance Review':'Evaluate performance over a regular review period.',
 '360° Feedback':'Gather feedback from multiple evaluator perspectives.',
 'Probationary Review':'Assess performance during the probation period.',
 'Project-Based Review':'Evaluate contributions to a specific project.'
};
/* Cycle-level evaluation configuration links existing employee goals; legacy launched cycles retain their snapshots. */
const cwBase={start:urStartWizard,wizard:urWizardPage,validation:urCycleValidation,commit:urCommitCycle,generate:urGenerateAssignments,detail:urReviewDetail,save:urSaveResponse,confirm:urConfirmSubmit,submit:urSubmitResponse,mean:urMean,dimensions:pdDimensionResults,results:urEmployeeResults,finalize:urDoFinalize,askFinalize:urFinalizeCycle,viewGoal:pmsViewGoal,goalPatch:pmsSaveGoalPatch,cycleList:urCycleList,cycleDetail:urCycleDetail};
const cwLegacyConfirmCycle=urConfirmCycle;
const cwBaseLookup=urDrawEmployeeLookup,cwBaseRead=urCanRead,cwBaseGoalUpdate=pmsCanUpdateGoalProgress;
const cwSteps=['Cycle Details','Select Participants','Evaluation Setup','Assessment Workflow','Review & Launch'];
let cwErrors=[],cwAttempted=new Set(),cwMaxStep=1,cwEmployeeFilter={q:'',department:'All departments',position:'All positions'},cwAssignment=null;
const cwStageAssignmentsOpen=new Set();
const cwV2=c=>c?.workflowVersion===2;
const cwPosition=id=>urPerson(id).position;
function cwEligibleGoalsTemplates(id){const position=cwPosition(id).trim().toLowerCase();return UR.goalTemplates.filter(t=>t.status==='Published'&&t.position.trim().toLowerCase()===position)}
function cwBehaviorEligible(t,id){return t?.status==='Published'&&(!t.positions?.length||t.positions.includes(cwPosition(id)))}
function cwBehaviorId(c,id){return c.behaviorByPosition?.[cwPosition(id)]||c.behavioralTemplate||''}
function cwBehaviorTemplate(c,id){return UR.templates.find(t=>t.id===cwBehaviorId(c,id))}
function cwLinks(c,id){return c.goalLinks?.[id]||[]}
function cwGoal(link){return data.goals.find(g=>String(g.id)===String(link.goalId))}
function cwAssigned(g,id){return !!g&&pmsGoalOwner(g)===id&&g.source!=='self'&&pmsGoalEmployeeInCompany(data.employees.find(e=>e[0]===id)||[])}
function cwPeriodGoal(g,c){return !!g.due&&g.due>=c.periodStart&&(g.startDate||g.due)<=c.periodEnd}
function cwGoalTemplate(c,id){return UR.goalTemplates.find(t=>t.id===c.goalTemplates?.[id])}
function cwDateValid(value){return /^\d{4}-\d{2}-\d{2}$/.test(value||'')&&!Number.isNaN(Date.parse(value))&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value}
function cwWeights(c){if(c.setupVersion===3)return {goals:50,behavioral:50};return {goals:c.components.goals?(c.components.behavioral?Number(c.weights.goals):100):0,behavioral:c.components.behavioral?(c.components.goals?Number(c.weights.behavioral):100):0}}
function cwNormalize(c){
 c.workflowVersion=2;c.components??={goals:true,behavioral:true};c.goalLinks??={};c.goalTemplates??={};c.behaviorByPosition??={};c.behavioralTemplate??='';c.weights??={goals:60,behavioral:40};c.scoring??={goals:'',behavioral:''};c.releasePolicy??={employee:true,manager:true};
 c.stages??=['Self','Manager','HR'].map((type,i)=>({id:urUid('stage'),name:pdLabel[type],type,deadline:['2026-11-06','2026-11-11','2026-11-15'][i],reviewer:type==='HR'?'HR-001':'',reviewers:{}}));
 c.stages.forEach(s=>{s.name=s.name?.trim()?s.name:pdLabel[s.type]||'';delete s.goalsTemplate;delete s.behavioralTemplate;s.reviewers??={}});c.deadline=c.stages.at(-1)?.deadline||'';return c;
}
function cwLegacyCycle(){return cwNormalize({...urNewCycle(),periodStart:'2026-01-01',periodEnd:'2026-12-31',deadline:'',stages:undefined})}
// Only editable drafts adopt the simplified MVP defaults; launched records retain their original policy.
function cwPrepareSetup(c){
 const oldStep=Number(c.savedStep)||1;
 if(c.setupVersion!==3){c.previousEvaluationSetup={components:urClone(c.components),weights:urClone(c.weights),scoring:urClone(c.scoring),releasePolicy:urClone(c.releasePolicy),savedStep:oldStep};c.savedStep=oldStep>=6?5:oldStep===5?4:oldStep}
 c.setupVersion=3;c.components={goals:true,behavioral:true};c.weights={goals:50,behavioral:50};c.scoring={goals:'manager-verified',behavioral:'average'};
 c.releasePolicy={...c.releasePolicy,employee:true,manager:true,mode:'manual-hr'};
 if(!c.behavioralTemplate)c.behavioralTemplate=(UR.templates.find(t=>t.id==='hr-core-behaviors-v2'&&t.status==='Published')||UR.templates.find(t=>t.status==='Published'&&(!t.positions?.length||c.participants.every(id=>t.positions.includes(cwPosition(id))))))?.id||'';
 c.savedStep=Math.max(1,Math.min(5,c.savedStep||1));return c;
}
function cwNewCycle(){return cwPrepareSetup(cwLegacyCycle())}
function cwTouch(){urDirty=true;if(urWizard)urWizard.deadline=urWizard.stages.at(-1)?.deadline||''}
function cwSet(key,value){urWizard[key]=value;cwTouch()}
function cwSetStage(index,key,value){const stage=urWizard.stages[index];stage[key]=value;if(key==='type'){stage.reviewers={};stage.reviewer=value==='HR'?'HR-001':''}cwTouch();if(key==='type')render()}
function cwLaunchErrors(c){return cwValidate(c,5)}
function cwValidate(c,through=5){
 const errors=[],add=(step,field,message)=>errors.push({step,field,message});
 if(!c.name?.trim())add(1,'cw-name','Enter a cycle name.');
 if(!['Standard Performance Review','360° Feedback','Probationary Review','Project-Based Review'].includes(c.type))add(1,'cw-type','Select a supported review type.');
 if(!cwDateValid(c.periodStart))add(1,'cw-periodStart','Enter a valid evaluation period start.');
 if(!cwDateValid(c.periodEnd)||c.periodEnd<c.periodStart)add(1,'cw-periodEnd','Evaluation Period End must be on or after its start.');
 if(!cwDateValid(c.start))add(1,'cw-start','Enter a valid assessment start date.');
 if(through>=2){if(!c.participants.length)add(2,'cw-participants','Select at least one employee.');if(new Set(c.participants).size!==c.participants.length)add(2,'cw-participants','Remove duplicate participants.');for(const id of c.participants)if(!pdScopedEmployees().some(e=>e[0]===id))add(2,'cw-participants',urPerson(id).name+' is outside your authorized company scope.')}
 if(through>=3){
  if(c.setupVersion===3&&(!c.components.goals||!c.components.behavioral))add(3,'cw-goals-readiness','Goals Performance and Behavioral Performance are required.');
  if(!c.components.goals&&!c.components.behavioral)add(3,'cw-components','Enable at least one evaluation component.');
  for(const id of c.participants){
   const name=urPerson(id).name;
   if(c.components.goals){
    const template=cwGoalTemplate(c,id),links=cwLinks(c,id);
    if(!template||!cwEligibleGoalsTemplates(id).some(t=>t.id===template.id))add(3,'cw-readiness-'+id,name+': assign a published Goals Template for '+cwPosition(id)+'.');
    if(!links.length)add(3,'cw-readiness-'+id,name+': missing assigned goals. Use Assign Goals in Step 3.');
    if(new Set(links.map(l=>String(l.goalId))).size!==links.length)add(3,'cw-readiness-'+id,name+': the same goal is mapped more than once.');
    for(const link of links){const goal=cwGoal(link);if(!cwAssigned(goal,id)||!cwPeriodGoal(goal,c))add(3,'cw-readiness-'+id,name+': linked goal is missing, outside the evaluation period, or belongs to another employee.');if(!template?.indicators.some(x=>x.id===link.indicatorId)||!Number.isFinite(link.target)||link.target<0||!Number.isFinite(link.weight)||link.weight<=0||![link.scoreMet,link.scoreBelow].every(n=>Number.isFinite(n)&&n>=1&&n<=5))add(3,'cw-readiness-'+id,name+': check indicator targets, scores, and weights.');}
    if(template?.indicators.some(x=>!links.some(l=>l.indicatorId===x.id)))add(3,'cw-readiness-'+id,name+': map every required template indicator to an actual assigned goal.');
    if(links.length&&Math.abs(links.reduce((sum,l)=>sum+l.weight,0)-100)>.01)add(3,'cw-readiness-'+id,name+': goal indicator weights must total 100%.');
   }
   if(c.components.behavioral&&!cwBehaviorEligible(cwBehaviorTemplate(c,id),id))add(3,'cw-behavior-'+cwPosition(id),name+': choose a published, compatible Behavioral Template.');
  }
  if(c.components.goals&&c.scoring.goals!=='manager-verified')add(3,'cw-goalsPolicy','Confirm the Goals Performance scoring policy.');
  if(c.components.behavioral&&!['average','Self','Manager','HR'].includes(c.scoring.behavioral))add(3,'cw-behaviorPolicy','Choose an explicit Behavioral Performance aggregation policy.');
  const weights=cwWeights(c);if(![weights.goals,weights.behavioral].every(n=>Number.isFinite(n)&&n>=0&&n<=100)||weights.goals+weights.behavioral!==100)add(3,'cw-weights','Evaluation weights must total 100%.');
 }
 if(through>=4){
  if(!c.stages.length)add(4,'cw-workflow','Add at least one assessment stage.');
  if(new Set(c.stages.map(s=>s.id)).size!==c.stages.length)add(4,'cw-workflow','Remove conflicting stage identifiers.');
  for(const [i,stage] of c.stages.entries()){
   const field='cw-stage-'+stage.id;
   if(!urTypes.includes(stage.type))add(4,field,'Stage '+(i+1)+': unsupported assessment type.');
   if(!cwDateValid(stage.deadline)||stage.deadline<c.start||i&&stage.deadline<=c.stages[i-1].deadline)add(4,field,'Stage '+(i+1)+': deadline must be on/after assessment start and strictly after the previous stage.');
   for(const subject of c.participants){const reviewer=pdStageReviewer(stage,subject),person=urPeople().find(p=>p.id===reviewer),companyPerson=data.employees.find(e=>e[0]===reviewer);if(!person||companyPerson&&!pmsGoalEmployeeInCompany(companyPerson)||stage.type==='Self'&&reviewer!==subject||stage.type!=='Self'&&reviewer===subject||stage.type==='HR'&&reviewer!=='HR-001')add(4,field,stage.name+': select an authorized evaluator for '+urPerson(subject).name+'.')}
  }
  if(c.components.goals&&!c.stages.some(s=>s.type==='Manager'))add(4,'cw-workflow','Goals Performance requires a Manager stage for verification.');
  if(c.components.behavioral&&c.scoring.behavioral!=='average'&&!c.stages.some(s=>s.type===c.scoring.behavioral))add(4,'cw-workflow','The selected authoritative behavioral evaluator must have an assessment stage.');
 }
 if(through>=5&&c.stages.at(-1)?.deadline<urToday)add(4,'cw-workflow','The final assessment deadline has passed. Update the stage schedule.');
 if(through>=4){if(!c.releasePolicy.employee||!c.releasePolicy.manager)add(4,'cw-release','Retain own-employee and permitted-manager access to released results.');if(c.stages.some(s=>['Peer','Upward'].includes(s.type))&&(!Number.isInteger(Number(c.threshold))||c.threshold<2||c.threshold>10))add(4,'cw-confidentiality','Anonymous feedback threshold must be a whole number from 2 to 10.')}
 return errors;
}
urCycleValidation=function(c,step){return cwV2(c)?cwValidate(c,step||5).map(e=>`Step ${e.step}: ${e.message}`):cwBase.validation(c,step)};
urDrawEmployeeLookup=function(){return cwV2(urWizard)?cwDrawParticipants():cwBaseLookup()};
urCanRead=function(a){const c=a&&urCycle(a.cycle);if(cwV2(c)&&!c.released&&a.reviewer!==urUser()&&!urHr()){
 if(c.releasePolicy.previousStages!=='responses'||!['Submitted','Completed'].includes(a.state))return false;
 const mine=pdStageRows(c,a.subject).filter(x=>x.reviewer===urUser()),index=c.stages.findIndex(s=>s.id===a.stage),readerIndex=Math.max(-1,...mine.map(x=>c.stages.findIndex(s=>s.id===x.stage)));if(index>=readerIndex)return false;
}return cwBaseRead(a)};
pmsCanUpdateGoalProgress=function(g){return cwBaseGoalUpdate(g)||!!g&&viewRole==='Employee'&&pmsGoalOwner(g)===urUser()&&pmsGoalInScope(g)&&UR.cycles.some(c=>cwV2(c)&&c.status==='Active'&&g.goalVerifications?.[c.id]?.state==='Returned')};
urConfirmCycle=function(state){
 if(!cwV2(urWizard))return cwLegacyConfirmCycle(state);
 if(!urHr())return;cwErrors=cwLaunchErrors(urWizard);
 if(urWizard.stages.at(-1)?.deadline<urToday)cwErrors.push({step:4,field:'cw-workflow',message:'The final assessment deadline has passed. Update the stage schedule.'});
 if(state==='Active'&&urWizard.start>urToday||state==='Scheduled'&&urWizard.start<=urToday)cwErrors.push({step:1,field:'cw-start',message:'Choose launch for a current start or scheduling for a future start.'});
 if(cwErrors.length){render();$('#cw-error-summary')?.focus();return}
 modal(state==='Scheduled'?'Schedule Review Cycle?':'Launch Review Cycle?','',`<div class="modalbody"><p>${esc(urWizard.name)} includes ${urWizard.participants.length} participants and ${urWizard.stages.length} assessment stages.</p><p>Existing assigned goals will be linked, not duplicated. Only the first eligible stage opens when the assessment schedule begins. Future stages require prior submission; results require HR finalization and release.</p></div>`,`<button onclick="closeModal()">Back to Setup</button><button class="primary" onclick="urCommitCycle('${state}')">${state==='Scheduled'?'Schedule Cycle':'Launch Cycle'}</button>`);
};
function cwInline(field){const messages=cwErrors.filter(e=>e.field===field);return messages.length?`<small class="cw-error" id="${esc(field)}-error" role="alert">${messages.map(e=>esc(e.message)).join(' ')}</small>`:''}
function cwInput(label,key,type='text',full=false,required=true){const id='cw-'+key,error=cwErrors.some(e=>e.field===id);return `<label class="${full?'cw-full':''}" for="${id}">${label}${required?' <span class="required">*</span>':''}${type==='textarea'?`<textarea id="${id}" rows="3" maxlength="2000" oninput="cwSet('${key}',this.value)">${esc(urWizard[key]||'')}</textarea>`:`<input id="${id}" type="${type}" ${required?'required':''} ${type==='text'?'maxlength="120"':''} value="${esc(urWizard[key]||'')}" aria-invalid="${error}" ${error?`aria-describedby="${id}-error"`:''} oninput="cwSet('${key}',this.value)">`}${cwInline(id)}</label>`}
function cwSection(title,description,content,action='',id=''){return `<section class="cw-section" ${id?`id="${esc(id)}"`:''}><div class="cw-section-heading"><div><h3>${title}</h3>${description?`<p>${description}</p>`:''}</div>${action}</div>${content}</section>`}
function cwNotice(text){return `<div class="notice cw-notice">${text}</div>`}
function cwErrorSummary(){return cwErrors.length?`<div class="cw-validation" id="cw-error-summary" role="alert" tabindex="-1"><b>Check the following before continuing</b><ul>${cwErrors.map(e=>`<li><button class="textbtn" onclick="cwGoError(${e.step},'${esc(e.field)}')">Step ${e.step} · ${esc(e.message)}</button></li>`).join('')}</ul></div>`:''}
function cwGoError(step,field){urStep=step;render();const target=document.getElementById(field);if(target){target.scrollIntoView({block:'center'});target.focus?.()}}
function cwGoStep(step,force=false){if(!urHr()||!cwV2(urWizard)||!Number.isInteger(step)||step<1||step>5)return;if(step>urStep&&!force){const through=step===3?2:step-1;cwErrors=cwValidate(urWizard,through);cwAttempted.add(urStep);if(cwErrors.length){render();$('#cw-error-summary')?.focus();return}}urStep=step;cwMaxStep=Math.max(cwMaxStep,step);cwErrors=[];render()}
urStartWizard=function(id,fresh=false){
 if(!urHr()||id&&urCycle(id)?.status!=='Draft')return;
 urGo(()=>{const existing=id?urCycle(id):!fresh?UR.draftCycle:null;urWizard=cwPrepareSetup(existing?cwNormalize(urClone(existing)):cwNewCycle());urWizard.status='Draft';urStep=urWizard.savedStep;cwMaxStep=urStep;cwErrors=[];cwAttempted.clear();cwStageAssignmentsOpen.clear();cwEmployeeFilter={q:'',department:'All departments',position:'All positions'};page='Reviews';urTab='Cycles';urScreen='wizard';pdView='';urDirty=false;render()});
};
function cwCycleDetails(c){return cwSection('Basic Information','',`<div class="cw-grid">${cwInput('Cycle Name','name','text') }<label for="cw-type">Review Type <span class="required">*</span><select id="cw-type" aria-describedby="cw-type-description" onchange="cwSet('type',this.value);document.getElementById('cw-type-description').textContent=cwReviewTypeDescriptions[this.value]">${Object.entries(cwReviewTypeDescriptions).map(([value,description])=>`<option value="${value}" ${c.type===value?'selected':''}>${value} — ${description}</option>`).join('')}</select><small id="cw-type-description" class="cw-field-description">${cwReviewTypeDescriptions[c.type]||'Choose the purpose of this review cycle.'}</small>${cwInline('cw-type')}</label>${cwInput('Description','description','textarea',true,false)}</div>`)+cwSection('Evaluation Period','The period of employee performance being evaluated.',`<div class="cw-grid">${cwInput('Evaluation Period Start','periodStart','date')}${cwInput('Evaluation Period End','periodEnd','date')}</div>`)+cwSection('Assessment Schedule','The first stage opens on this date. The final deadline comes from the last stage in Step 4.',`<div class="cw-grid">${cwInput('Assessment Start Date','start','date')}</div>`)}
function cwEmployeeRows(){return pdScopedEmployees().filter(e=>e.slice(0,5).join(' ').toLowerCase().includes(cwEmployeeFilter.q.toLowerCase())&&(cwEmployeeFilter.department==='All departments'||e[3]===cwEmployeeFilter.department)&&(cwEmployeeFilter.position==='All positions'||e[2]===cwEmployeeFilter.position))}
function cwEmployeeSearch(key,value){cwEmployeeFilter[key]=value;cwDrawParticipants()}
function cwToggleParticipant(id,checked){if(!urHr()||!pdScopedEmployees().some(e=>e[0]===id))return;urWizard.participants=checked?[...new Set([...urWizard.participants,id])]:urWizard.participants.filter(x=>x!==id);if(checked)cwLinkExistingGoals(urWizard,id);cwTouch();render()}
function cwDrawParticipants(){const all=cwEmployeeRows(),visible=pdSlice('cw-participants',all,JSON.stringify(cwEmployeeFilter));$('#cw-participant-table').innerHTML=pdTable(['SELECT','EMPLOYEE','EMPLOYEE ID','DEPARTMENT','POSITION','MANAGER'],visible.map(e=>`<tr><td><input type="checkbox" aria-label="Select ${esc(e[1])}" ${urWizard.participants.includes(e[0])?'checked':''} onchange="cwToggleParticipant('${e[0]}',this.checked)"></td><td>${urDisplayPerson(e[0])}</td><td>${e[0]}</td><td>${esc(e[3])}</td><td>${esc(e[2])}</td><td>${esc(pmsManagerName(e[0]))}</td></tr>`).join(''),'cw-participants',all.length,'cwDrawParticipants')}
function cwReadiness(c,actions=true){return `<div class="tablewrap"><table><thead><tr><th>EMPLOYEE</th><th>APPLICABLE GOALS TEMPLATE</th><th>GOAL READINESS</th>${actions?'<th>GOAL CONFIGURATION</th>':''}</tr></thead><tbody>${c.participants.map(id=>{const template=cwGoalTemplate(c,id),links=cwLinks(c,id),valid=links.filter(l=>cwAssigned(cwGoal(l),id)&&cwPeriodGoal(cwGoal(l),c));return `<tr id="cw-readiness-${id}" tabindex="-1"><td>${urDisplayPerson(id)}</td><td>${esc(template?.name||'Not Assigned')}<small>${esc(cwPosition(id))}</small></td><td>${urBadge(!c.components.goals?'Not required':valid.length?valid.length+' Goals Available':'Missing Goals')}${cwInline('cw-readiness-'+id)}</td>${actions?`<td><button class="textbtn" onclick="cwAssignGoals('${id}')">${links.length?'Review Goals':'Assign Goals'}</button></td>`:''}</tr>`}).join('')||`<tr><td colspan="${actions?4:3}" class="empty">Select employees to check their goal readiness.</td></tr>`}</tbody></table></div>`}
function cwParticipants(c){const people=pdScopedEmployees();return cwSection('Select Employees','Select existing HRDotNet employees. Selection persists across filters and pages.',`<div class="toolbar urtoolbar"><label class="urfilter ursearch">Search Employees<input class="search" placeholder="Search employees..." value="${esc(cwEmployeeFilter.q)}" oninput="cwEmployeeSearch('q',this.value)"></label>${pmsToolbarSelect('Department',cwEmployeeFilter.department,['All departments',...new Set(people.map(e=>e[3]))],"cwEmployeeSearch('department',this.value)")}${pmsToolbarSelect('Position',cwEmployeeFilter.position,['All positions',...new Set(people.map(e=>e[2]))],"cwEmployeeSearch('position',this.value)")}<span class="pill blue">${c.participants.length} selected</span></div><div id="cw-participant-table"></div>${cwInline('cw-participants')}`,'','cw-participants')}
function cwAssignmentRows(t,subject,c=urWizard){return t.indicators.map(x=>{const link=cwLinks(c,subject).find(l=>l.indicatorId===x.id),linked=link&&cwGoal(link),g=cwAssigned(linked,subject)&&cwPeriodGoal(linked,c)?linked:data.goals.find(g=>cwAssigned(g,subject)&&cwPeriodGoal(g,c)&&g.name.trim().toLowerCase()===x.name.trim().toLowerCase());return {...urClone(x),...(linked===g?link||{}:{}),goalId:g?String(g.id):'new',deadline:g?.due||c.periodEnd}})}
function cwLinkExistingGoals(c,subject){if(cwLinks(c,subject).length)return;const t=cwEligibleGoalsTemplates(subject).find(t=>cwAssignmentRows(t,subject,c).every(r=>r.goalId!=='new'));if(!t)return;c.goalTemplates[subject]=t.id;c.goalLinks[subject]=cwAssignmentRows(t,subject,c).map(r=>({goalId:Number(r.goalId),indicatorId:r.id,target:r.target,unit:r.unit,direction:r.direction,weight:r.weight,scoreMet:r.scoreMet,scoreBelow:r.scoreBelow,requiresVerification:true}))}
function cwTemplateChanged(id){if(!cwAssignment)return;const t=cwEligibleGoalsTemplates(cwAssignment.subject).find(t=>t.id===id);cwAssignment.templateId=id;cwAssignment.rows=t?cwAssignmentRows(t,cwAssignment.subject):[];cwAssignmentPage()}
function cwAssignGoals(subject){if(!urHr()||!urWizard.participants.includes(subject))return;const t=cwGoalTemplate(urWizard,subject)||cwEligibleGoalsTemplates(subject)[0];cwAssignment={subject,templateId:t?.id||'',rows:t?cwAssignmentRows(t,subject):[]};cwAssignmentPage()}
function cwAssignmentPage(){const d=cwAssignment;if(!urHr()||!d)return;const choices=data.goals.filter(g=>cwAssigned(g,d.subject)&&cwPeriodGoal(g,urWizard));modal('Assign Employee Goals',urPerson(d.subject).name+' · '+cwPosition(d.subject),`<form id="cwAssignmentForm" onsubmit="event.preventDefault();cwSaveAssignment()"><div class="modalbody cw-assignment"><label>Applicable Goals Template<select onchange="cwTemplateChanged(this.value)"><option value="">Select a position-specific template</option>${cwEligibleGoalsTemplates(d.subject).map(t=>`<option value="${t.id}" ${d.templateId===t.id?'selected':''}>${esc(t.name)} · v${t.version} — ${esc(urTemplateDescription(t))}</option>`).join('')}</select></label>${!cwEligibleGoalsTemplates(d.subject).length?cwNotice('No published template matches this position. Publish a matching Goals Template before assigning goals.')+'<button type="button" onclick="hrOpenMatchingTemplate()">Create Matching Goals Template</button>':''}${d.rows.map((r,i)=>`<section class="cw-assignment-row"><b>${esc(r.name)}</b><div class="cw-grid"><label>Actual Goal Record<select onchange="cwAssignment.rows[${i}].goalId=this.value;cwAssignmentSelected(${i})"><option value="new">Create assigned goal from this indicator</option>${choices.map(g=>`<option value="${g.id}" ${String(r.goalId)===String(g.id)?'selected':''}>${esc(g.name)} · ${g.progress}%</option>`).join('')}</select></label><label>Employee-specific target (${esc(r.unit)})<input type="number" min="0" step="any" value="${r.target}" oninput="cwAssignment.rows[${i}].target=Number(this.value)"></label><label>Goal Deadline <span class="required">*</span><input type="date" required value="${r.deadline}" oninput="cwAssignment.rows[${i}].deadline=this.value"></label><div class="cw-criteria">${r.direction==='Lower'?'At or below':'At or above'} target: ${r.scoreMet}/5; otherwise ${r.scoreBelow}/5. Weight: ${r.weight}%.</div></div></section>`).join('')}<p class="urmuted">Saving creates or links real assigned goals in the Goals module, with the confirmed targets and deadlines. Existing progress is preserved. It does not launch the cycle.</p><div id="cwAssignmentError" class="cw-error" role="alert"></div></div><div class="modalfoot"><button type="button" onclick="cwAssignment=null;closeModal()">Cancel</button><button class="primary" ${d.rows.length?'':'disabled'}>Save Goal Assignment</button></div></form>`,'')}
function cwAssignmentSelected(index){const row=cwAssignment.rows[index],g=data.goals.find(g=>String(g.id)===row.goalId);if(g)row.deadline=g.due;cwAssignmentPage()}
function cwSaveAssignment(){
 const d=cwAssignment,c=urWizard;if(!urHr()||!d||!c.participants.includes(d.subject)||!pdScopedEmployees().some(e=>e[0]===d.subject))return;
 const t=cwEligibleGoalsTemplates(d.subject).find(t=>t.id===d.templateId),ids=d.rows.filter(r=>r.goalId!=='new').map(r=>r.goalId);
 if(!t||!d.rows.length||d.rows.some(r=>!Number.isFinite(r.target)||r.target<0||!cwDateValid(r.deadline)||r.deadline<c.periodStart||r.deadline>c.periodEnd||r.goalId!=='new'&&!cwAssigned(data.goals.find(g=>String(g.id)===r.goalId),d.subject))||new Set(ids).size!==ids.length){$('#cwAssignmentError').textContent='Confirm valid targets and evaluation-period deadlines. Select each existing goal only once.';return}
 const owner=urPerson(d.subject);c.goalTemplates[d.subject]=t.id;c.goalLinks[d.subject]=d.rows.map(r=>{
  let g=r.goalId==='new'?null:data.goals.find(g=>String(g.id)===r.goalId);
  if(!g){g={id:pmsGoalId(),name:r.name,description:r.description||'Assigned from '+t.name,employee:owner.name,ownerId:d.subject,createdBy:urUser(),createdByName:roleName(),createdAt:pdNow(),assignedBy:roleName(),source:'assigned',category:'Delivery',startDate:c.periodStart,due:r.deadline,cycle:c.id,progress:0,trackingMode:'manual',milestones:[],status:'Active',updates:[]};data.goals.push(g)}else g.due=r.deadline;
  g.cycleId??=c.id;g.evaluationCycles=[...new Set([...(g.evaluationCycles||[]),c.id])];g.evaluationTargets??={};g.evaluationTargets[c.id]={target:r.target,unit:r.unit};
  return {goalId:g.id,indicatorId:r.id,target:r.target,unit:r.unit,direction:r.direction,weight:r.weight,scoreMet:r.scoreMet,scoreBelow:r.scoreBelow,requiresVerification:true};
 });cwAssignment=null;cwTouch();closeModal();urSaveCycleDraft();toast('Actual employee goals linked to this draft cycle');
}
function cwReady(c,id){return !cwValidate(c,3).some(e=>e.field==='cw-readiness-'+id)}
function cwAvailableGoalLinks(c,id){const seen=new Set();return cwLinks(c,id).filter(l=>{const key=String(l.goalId);if(seen.has(key)||!cwAssigned(cwGoal(l),id)||!cwPeriodGoal(cwGoal(l),c))return false;seen.add(key);return true})}
function cwEvaluationGoals(c){
 const ready=c.participants.filter(id=>cwReady(c,id)).length;
 return cwSection('Goals Performance','Review the assigned goals that will be included in this evaluation.',`<p class="cw-readiness-summary" id="cw-goals-readiness" role="status">${ready} of ${c.participants.length} participants ready.</p><div class="tablewrap"><table><thead><tr><th scope="col">EMPLOYEE</th><th scope="col">APPLICABLE GOALS TEMPLATE</th><th scope="col">ASSIGNED GOALS</th><th scope="col">ACTION</th></tr></thead><tbody>${c.participants.map(id=>{const t=cwEligibleGoalsTemplates(id).find(t=>t.id===c.goalTemplates[id]),links=cwAvailableGoalLinks(c,id);return `<tr id="cw-readiness-${id}" tabindex="-1"><td>${urDisplayPerson(id)}</td><td>${esc(t?.status==='Published'?t.name:'No applicable published template')}${t?.status==='Published'?`<small>Version ${t.version}</small>`:''}</td><td>${links.length?`${links.length} assigned goals`:'No goals assigned'}${cwInline('cw-readiness-'+id)}</td><td><button type="button" class="textbtn" onclick="${links.length?'cwReviewGoals':'cwAssignGoals'}('${id}')">${links.length?'Review Goals':'Assign Goals'}</button></td></tr>`}).join('')||'<tr><td colspan="4" class="empty">Select participants in Step 2 to review their assigned goals.</td></tr>'}</tbody></table></div>${cwInline('cw-goals-readiness')}`);
}
function cwReviewGoals(subject){
 const c=urWizard;if(!urHr()||!cwV2(c)||!c.participants.includes(subject)||!pdScopedEmployees().some(e=>e[0]===subject))return;
 const links=cwAvailableGoalLinks(c,subject);
 modal('Assigned Employee Goals',urPerson(subject).name+' · '+cwPosition(subject),`<div class="modalbody cw-assignment"><p>Actual assigned goals included in ${esc(c.name||'this evaluation')}.</p><div class="tablewrap"><table><thead><tr><th scope="col">GOAL NAME</th><th scope="col">TARGET</th><th scope="col">PROGRESS</th><th scope="col">DEADLINE</th></tr></thead><tbody>${links.map(l=>{const g=cwGoal(l);return `<tr><td><b>${esc(g.name)}</b></td><td>${l.target} ${esc(l.unit)}</td><td>${progress(g.progress)}</td><td>${date(g.due)}</td></tr>`}).join('')||'<tr><td colspan="4" class="empty">No goals assigned.</td></tr>'}</tbody></table></div></div>`,`<button type="button" onclick="closeModal()">Back to Evaluation Setup</button><button type="button" class="primary" onclick="cwAssignGoals('${subject}')">Manage Goal Assignment</button>`);
}
function cwBehaviorSelectors(c){
 const positions=[...new Set(c.participants.map(cwPosition))],template=UR.templates.find(t=>t.id===c.behavioralTemplate);
 return `<div class="cw-behavior-default"><label for="cw-behavioralTemplate"><span class="hr-field-label">Behavioral Template <span class="required">*</span></span><select id="cw-behavioralTemplate" required aria-invalid="${cwErrors.some(e=>e.field.startsWith('cw-behavior-'))}" onchange="cwSet('behavioralTemplate',this.value);render()"><option value="">Select a published template</option>${UR.templates.filter(t=>t.status==='Published').map(t=>`<option value="${t.id}" ${c.behavioralTemplate===t.id?'selected':''}>${esc(t.name)} · v${t.version} — ${esc(urTemplateDescription(t))}</option>`).join('')}</select></label>${template?.status==='Published'?`<div class="cw-template-meta"><div><span>Version ${template.version} · ${template.questions.length} questions</span><p class="cw-field-description">${esc(urTemplateDescription(template))}</p></div><button type="button" onclick="urPreviewTemplate('${template.id}')">Preview Template</button></div>`:''}</div><details class="cw-position-mapping"><summary>Customize by Position</summary><div class="cw-grid">${positions.map((position,i)=>`<label for="cw-position-${i}">${esc(position)}<select id="cw-position-${i}" onchange="urWizard.behaviorByPosition[${JSON.stringify(position).replaceAll('"','&quot;')}]=this.value;cwTouch();render()"><option value="">Use cycle default</option>${UR.templates.filter(t=>t.status==='Published'&&(!t.positions?.length||t.positions.includes(position))).map(t=>`<option value="${t.id}" ${c.behaviorByPosition[position]===t.id?'selected':''}>${esc(t.name)} · v${t.version} — ${esc(urTemplateDescription(t))}</option>`).join('')}</select></label>`).join('')}</div></details>${positions.map(position=>cwInline('cw-behavior-'+position)).join('')}`;
}
function cwSetup(c){return cwEvaluationGoals(c)+cwSection('Behavioral Performance','Select the behavioral template used to assess workplace behaviors.',cwBehaviorSelectors(c))}

function cwStageLabel(stage){return pdLabel[stage.type]||stage.name||'Assessment'}
function cwEvaluatorChoices(stage,subject){return urPeople().filter(p=>p.id!==subject&&(stage.type!=='HR'||p.id==='HR-001')&&(!data.employees.some(e=>e[0]===p.id)||pdScopedEmployees().some(e=>e[0]===p.id)))}
function cwStageHasEvaluator(stage,subject){const id=pdStageReviewer(stage,subject);return stage.type==='Self'?id===subject:!!cwEvaluatorChoices(stage,subject).find(p=>p.id===id)}
function cwSetStageReviewer(stageId,subject,reviewer){
 const stage=urWizard?.stages.find(s=>s.id===stageId);if(!urHr()||!cwV2(urWizard)||!stage||['Self','Manager'].includes(stage.type)||!urWizard.participants.includes(subject)||!pdScopedEmployees().some(e=>e[0]===subject)||reviewer&&!cwEvaluatorChoices(stage,subject).some(p=>p.id===reviewer))return;
 stage.reviewers??={};stage.reviewers[subject]=reviewer;cwTouch();render();
}
function cwSetAssignmentsOpen(id,open){if(!urHr()||!urWizard?.stages.some(s=>s.id===id))return;open?cwStageAssignmentsOpen.add(id):cwStageAssignmentsOpen.delete(id)}
function cwStageAssignments(c,stage){
 const key='cw-assignments-'+stage.id,rows=pdSlice(key,c.participants,JSON.stringify(c.participants)),assigned=c.participants.filter(id=>cwStageHasEvaluator(stage,id)).length;
 return `<details class="cw-stage-assignments" ${cwStageAssignmentsOpen.has(stage.id)?'open':''} ontoggle="cwSetAssignmentsOpen('${stage.id}',this.open)"><summary aria-label="View Assignments for ${esc(cwStageLabel(stage))}"><span class="cw-assignment-summary"><strong>Evaluator Assignments</strong><small>${c.participants.length} employees · ${assigned} assigned</small></span><span class="cw-view-assignments">View Assignments${pmsChevron()}</span></summary>${pdTable(['EMPLOYEE','ASSIGNED EVALUATOR'],rows.map(subject=>`<tr><td>${urDisplayPerson(subject)}</td><td>${['Self','Manager'].includes(stage.type)?esc(urPerson(pdStageReviewer(stage,subject)).name):`<select aria-label="Assigned evaluator for ${esc(urPerson(subject).name)} in ${esc(cwStageLabel(stage))}" onchange="cwSetStageReviewer('${stage.id}','${subject}',this.value)"><option value="">Select evaluator</option>${cwEvaluatorChoices(stage,subject).map(p=>`<option value="${p.id}" ${pdStageReviewer(stage,subject)===p.id?'selected':''}>${esc(p.name)} · ${esc(p.position)}</option>`).join('')}</select>`}</td></tr>`).join(''),key,c.participants.length,'render')}</details>`;
}
function cwMoveOptionalStage(index,delta){if(!urHr()||!cwV2(urWizard)||!['Peer','Upward'].includes(urWizard.stages[index]?.type)||!['Peer','Upward'].includes(urWizard.stages[index+delta]?.type))return;pdMoveStage(index,delta)}
function cwRemoveOptionalStage(index){if(!urHr()||!cwV2(urWizard)||!['Peer','Upward'].includes(urWizard.stages[index]?.type))return;cwStageAssignmentsOpen.delete(urWizard.stages[index].id);urWizard.stages.splice(index,1);cwTouch();render()}
function cwWorkflow(c){
 const content=[c.components.goals?'Goals Performance':null,c.components.behavioral?'Behavioral Performance':null].filter(Boolean).join(' + ')||'No evaluation components configured';
 return cwSection('Assessment Stages & Deadlines','Set the deadline in each stage card below. Stages unlock per employee after the preceding assessment is submitted.',`<ol class="cw-sequence">${c.stages.map((stage,i)=>`<li><span>${i+1}</span>${esc(cwStageLabel(stage))}</li>`).join('')}</ol><div id="cw-workflow">${cwInline('cw-workflow')}${c.stages.map((stage,i)=>`<section class="cw-stage" id="cw-stage-${stage.id}" tabindex="-1"><div class="cw-stage-header"><h4>Stage ${i+1} · ${esc(cwStageLabel(stage))}</h4>${['Peer','Upward'].includes(stage.type)?`<div class="cw-stage-actions"><button type="button" aria-label="Move stage ${i+1} up" ${!['Peer','Upward'].includes(c.stages[i-1]?.type)?'disabled':''} onclick="cwMoveOptionalStage(${i},-1)">↑</button><button type="button" aria-label="Move stage ${i+1} down" ${!['Peer','Upward'].includes(c.stages[i+1]?.type)?'disabled':''} onclick="cwMoveOptionalStage(${i},1)">↓</button><button type="button" onclick="cwRemoveOptionalStage(${i})">Remove</button></div>`:''}</div><div class="cw-grid cw-stage-fields"><label for="cw-deadline-${stage.id}"><span class="hr-field-label">${esc(cwStageLabel(stage))} Deadline <span class="required">*</span></span><input id="cw-deadline-${stage.id}" type="date" required aria-label="${esc(cwStageLabel(stage))} Deadline" value="${stage.deadline}" min="${i?c.stages[i-1].deadline:c.start}" oninput="cwSetStage(${i},'deadline',this.value)"></label><label for="cw-content-${stage.id}"><span class="hr-field-label">Assessment Content</span><input id="cw-content-${stage.id}" class="cw-stage-content" type="text" disabled readonly value="${esc(content)}"></label></div>${cwStageAssignments(c,stage)}${cwInline('cw-stage-'+stage.id)}</section>`).join('')}</div><button type="button" onclick="urWizard.stages.push({id:urUid('stage'),name:'Peer Assessment',type:'Peer',deadline:'',reviewer:'',reviewers:{}});cwTouch();render()">+ Add Assessment Stage</button><p class="cw-help">Final assessment deadline: ${cwDateValid(c.stages.at(-1)?.deadline)?date(c.stages.at(-1).deadline):'Not configured'}. A missed deadline does not unlock the next stage.</p>`)+cwRelease(c);
}

function cwPolicyLabel(c){return c.scoring.behavioral==='average'?'Average eligible observed ratings across named stages':c.scoring.behavioral?`${c.scoring.behavioral} assessment is authoritative`:'Not configured'}
function cwRelease(c){const types=c.stages.map(s=>s.type);return cwSection('Result Release','Manual release by HR Administrator.',`<p>HR finalizes completed assessments, then releases the results. Neither action takes place during cycle setup.</p><details class="cw-position-mapping"><summary>Feedback Visibility</summary><label class="cw-previous-access">Previous-stage information for evaluators<select onchange="urWizard.releasePolicy.previousStages=this.value;cwTouch()"><option value="metadata" ${c.releasePolicy.previousStages!=='responses'?'selected':''}>Stage status and submission metadata only</option><option value="responses" ${c.releasePolicy.previousStages==='responses'?'selected':''}>Permitted named responses from prior stages</option></select></label>${types.includes('Peer')?`<label class="cw-check"><input type="checkbox" ${c.anonymousPeer?'checked':''} onchange="cwSet('anonymousPeer',this.checked)">Protect anonymous Peer Feedback</label>`:''}${types.includes('Upward')?`<label class="cw-check"><input type="checkbox" ${c.anonymousUpward?'checked':''} onchange="cwSet('anonymousUpward',this.checked)">Protect anonymous Upward Feedback</label>`:''}${types.some(t=>['Peer','Upward'].includes(t))?`<label id="cw-confidentiality">Minimum anonymous responses <span class="required">*</span><input type="number" min="2" max="10" value="${c.threshold}" oninput="cwSet('threshold',Number(this.value))">${cwInline('cw-confidentiality')}</label>`:''}</details>${cwInline('cw-release')}`)}

function cwSummary(c){const errors=cwLaunchErrors(c),ready=c.participants.filter(id=>cwReady(c,id)).length,t=UR.templates.find(t=>t.id===c.behavioralTemplate);return cwSection('Cycle Overview','',`<div class="cw-summary-pairs">${[['Cycle Name',c.name],['Review Type',c.type],['Evaluation Period',date(c.periodStart)+' – '+date(c.periodEnd)],['Assessment Start Date',date(c.start)]].map(([k,v])=>`<div><small>${k}</small><b>${esc(String(v))}</b></div>`).join('')}</div>`, '<button class="textbtn" onclick="cwGoStep(1,true)">Edit Cycle Details</button>')+cwSection('Selected Participants & Goal Readiness',`${ready} of ${c.participants.length} participants ready.`,cwReadiness(c,false),'<button class="textbtn" onclick="cwGoStep(3,true)">Review Evaluation Setup</button>')+cwSection('Behavioral Template','',`<p><b>${esc(t?.name||'No default template selected')}</b>${t?' · Version '+t.version+' · '+t.questions.length+' questions':''}</p>${Object.entries(c.behaviorByPosition).filter(([position,id])=>id&&c.participants.some(subject=>cwPosition(subject)===position)).map(([position,id])=>{const mapped=UR.templates.find(t=>t.id===id);return `<p>${esc(position)}: ${esc(mapped?.name||'Template unavailable')}${mapped?' · v'+mapped.version:''}</p>`}).join('')}`)+cwSection('Assessment Workflow','',`<div class="tablewrap"><table><thead><tr><th scope="col">SEQUENCE</th><th scope="col">STAGE</th><th scope="col">EMPLOYEE → EVALUATOR</th><th scope="col">DEADLINE</th></tr></thead><tbody>${c.stages.map((s,i)=>`<tr><td>${i+1}</td><td>${esc(s.name)}</td><td>${c.participants.map(id=>`${esc(urPerson(id).name)} → ${esc(urPerson(pdStageReviewer(s,id)).name)}`).join('<br>')}</td><td>${cwDateValid(s.deadline)?date(s.deadline):'Missing deadline'}</td></tr>`).join('')}</tbody></table></div><p>Result release: Manual release by HR Administrator.</p>`,'<button class="textbtn" onclick="cwGoStep(4,true)">Edit Assessment Workflow</button>')+(errors.length?cwSection('Validation Summary','',`<div class="cw-validation" role="alert"><b>Resolve ${errors.length} blocking issue${errors.length===1?'':'s'}</b><ul>${errors.map(e=>`<li><button class="textbtn" onclick="cwGoError(${e.step},'${esc(e.field)}')">Step ${e.step} · ${esc(e.message)}</button></li>`).join('')}</ul></div>`):cwNotice('Ready to launch. Assessments open sequentially; HR finalization and manual release follow completion.'))}

urWizardPage=function(){if(!cwV2(urWizard))return cwBase.wizard();const c=urWizard,errors=urStep===5?cwLaunchErrors(c):[],body=[cwCycleDetails,cwParticipants,cwSetup,cwWorkflow,cwSummary][urStep-1](c);return pdBack("urGoTab('Cycles')",'Back to Cycles')+pdHead('Create Review Cycle','Connect employee goals, evaluation components, and sequential assessments.')+`<div class="urstepper cw-stepper" aria-label="Review cycle steps">${cwSteps.map((label,i)=>`<button class="${urStep===i+1?'active':i+1<cwMaxStep?'done':''}" ${urStep===i+1?'aria-current="step"':''} onclick="cwGoStep(${i+1})"><span>${i+1<cwMaxStep?'✓':i+1}</span>${label}</button>`).join('')}</div><section class="panel cw-wizard"><div class="cw-wizard-title"><small>STEP ${urStep} OF 5</small><h2>${cwSteps[urStep-1]}</h2></div><div class="cw-wizard-body">${cwErrorSummary()}${body}</div><footer class="cw-footer"><span>${c.participants.length} selected · Changes ${urDirty?'not saved':'saved or unchanged'}</span><div><button onclick="urSaveCycleDraft()">Save as Draft</button>${urStep>1?`<button onclick="cwGoStep(${urStep-1})">Back</button>`:''}${urStep<5?`<button class="primary" onclick="cwGoStep(${urStep+1})">Continue</button>`:`<button class="primary" ${errors.length?'disabled':''} onclick="urConfirmCycle('${c.start>urToday?'Scheduled':'Active'}')">${c.start>urToday?'Schedule':'Launch'} Cycle</button>`}</div></footer></section>`};

/* A single set of linked goals supplies every assessment stage and the consolidated result. */
function cwGenerate(c){if(UR.assignments.some(a=>a.cycle===c.id))return;for(const stage of c.stages)for(const subject of c.participants){const template=c.components.behavioral?c.behaviorSnapshots?.[cwPosition(subject)]||cwBehaviorTemplate(c,subject):{id:'goals-only',name:'Goals Performance',description:'',version:1,sections:[],questions:[]};UR.assignments.push({id:urUid('rev'),cycle:c.id,subject,reviewer:pdStageReviewer(stage,subject),type:stage.type,stage:stage.id,deadline:stage.deadline,template:urClone(template),state:'Not Started',answers:{},feedback:'',updated:urToday})}}
urGenerateAssignments=function(c){return cwV2(c)?cwGenerate(c):cwBase.generate(c)};
urCommitCycle=function(state){if(!cwV2(urWizard))return cwBase.commit(state);if(!urHr()||!['Active','Scheduled'].includes(state)||cwLaunchErrors(urWizard).length)return;const c=urClone(urWizard);if(state==='Active'&&(c.start>urToday||c.stages.at(-1).deadline<urToday)||state==='Scheduled'&&c.start<=urToday)return;if(UR.assignments.some(a=>a.cycle===c.id))return;c.status=state;c.name=c.name.trim();if(c.components.goals)for(const subject of c.participants)for(const link of cwLinks(c,subject)){const g=cwGoal(link);g.cycleId??=c.id;g.evaluationCycles=[...new Set([...(g.evaluationCycles||[]),c.id])];g.evaluationTargets??={};g.evaluationTargets[c.id]={target:link.target,unit:link.unit}}c.deadline=c.stages.at(-1).deadline;c.weights=cwWeights(c);c.groups=[...new Set(c.stages.map(s=>s.type))];c.evaluators=c.stages.flatMap(s=>c.participants.map(subject=>({subject,type:s.type,reviewer:pdStageReviewer(s,subject)})));c.templates={};c.behaviorSnapshots=Object.fromEntries([...new Set(c.participants.map(cwPosition))].map(position=>{const id=c.participants.find(id=>cwPosition(id)===position);return [position,c.components.behavioral?urClone(cwBehaviorTemplate(c,id)):null]}));c.goalTemplateSnapshots=Object.fromEntries(c.participants.map(id=>[id,c.components.goals?urClone(cwGoalTemplate(c,id)):null]));const index=UR.cycles.findIndex(x=>x.id===c.id);if(index>=0)UR.cycles[index]=c;else UR.cycles.push(c);if(state==='Active')cwGenerate(c);UR.draftCycle=null;urDirty=false;urAudit('Connected review cycle '+state+': '+c.id);closeModal();urDetail=c.id;urDetailTab='Overview';urTab='Cycles';urScreen='cycle';render();toast('Cycle saved; assessments follow the configured sequence')};
function cwGoalActual(g,c){return g?.evaluationActuals?.[c.id]?.value??null}
function cwGoalSignature(g,c){return JSON.stringify([pmsGoalOwner(g),g.name,g.due,g.progress,pmsMilestoneSignature(pmsGoalMilestones(g)),cwGoalActual(g,c)])}
function cwVerification(g,c){const v=g?.goalVerifications?.[c.id];if(!v)return 'Not submitted';return v.signature!==cwGoalSignature(g,c)?'Changed — verify again':v.state}
function cwCanManageVerification(g,c){return !!g&&cwV2(c)&&c.status==='Active'&&!c.released&&viewRole==='Manager'&&pmsGoalInScope(g)&&urTeam(pmsGoalOwner(g))&&UR.assignments.some(a=>a.cycle===c.id&&a.subject===pmsGoalOwner(g)&&a.type==='Manager'&&a.reviewer===urUser()&&pdUnlocked(a)&&!['Submitted','Completed'].includes(a.state))}
function cwCanRecord(g,c){return !!g&&cwV2(c)&&['Draft','Active'].includes(c.status)&&!c.released&&pmsGoalInScope(g)&&pmsGoalOwner(g)===urUser()&&cwLinks(c,pmsGoalOwner(g)).some(l=>String(l.goalId)===String(g.id))}
function cwRecordActual(id,cycle){const g=data.goals.find(g=>String(g.id)===String(id)),c=urCycle(cycle);if(!cwCanRecord(g,c))return;const link=cwLinks(c,pmsGoalOwner(g)).find(l=>String(l.goalId)===String(id));modal('Record Goal Achievement',g.name,`<form onsubmit="event.preventDefault();cwSaveActual('${id}','${cycle}',this)"><div class="modalbody"><p>Progress remains ${g.progress}%. Recording an actual result does not change progress or automatically verify completion.</p><label>Actual Result (${esc(link.unit)}) <span class="required">*</span><input name="actual" type="number" min="0" step="any" required value="${cwGoalActual(g,c)??''}"></label><p>${Number(g.progress)===100?'Saving submits the completed goal for Manager verification.':'Saving reports achievement for Manager review. Submit completion after the goal reaches 100%.'}</p><div id="cwActualError" class="cw-error" role="alert"></div></div><div class="modalfoot"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">${Number(g.progress)===100?'Submit for Verification':'Save Recorded Actual'}</button></div></form>`,'')}
function cwSaveActual(id,cycle,form){const g=data.goals.find(g=>String(g.id)===String(id)),c=urCycle(cycle),raw=new FormData(form).get('actual');if(!cwCanRecord(g,c))return;const value=Number(raw);if(raw==null||raw===''||!Number.isFinite(value)||value<0){$('#cwActualError').textContent='Enter a valid nonnegative actual result.';return}g.evaluationActuals??={};g.evaluationActuals[c.id]={value,by:urUser(),at:pdNow()};cwVerificationEvent(g,c,Number(g.progress)===100?'Pending':'Reported','');urAudit('Goal actual recorded: '+g.id+' / '+c.id);closeModal();render();toast('Goal achievement recorded for Manager review')}
function cwVerificationEvent(g,c,state,reason){g.goalVerifications??={};const old=g.goalVerifications[c.id];g.goalVerifications[c.id]={state,reason,by:urUser(),at:pdNow(),signature:cwGoalSignature(g,c),completionVerified:state==='Verified'&&Number(g.progress)===100,history:[...(old?.history||[]),{state,reason,by:urUser(),at:pdNow()}]}}
function cwVerifyGoal(id,cycle,action){const g=data.goals.find(g=>String(g.id)===String(id)),c=urCycle(cycle);if(!cwCanManageVerification(g,c)||!['Verified','Returned'].includes(action))return;modal(action==='Verified'?'Verify Goal Achievement?':'Return Goal for Revision',g.name,`<form onsubmit="event.preventDefault();cwConfirmVerification('${id}','${cycle}','${action}',this)"><div class="modalbody"><p>Recorded actual: ${cwGoalActual(g,c)??'Not recorded'} · Progress: ${g.progress}%.</p>${action==='Returned'?'<label>Reason for Revision <span class="required">*</span><textarea name="reason" required maxlength="2000" rows="3"></textarea></label>':'<p>Verify the recorded actual result against supporting evidence. This does not alter the employee\'s goal progress.</p>'}<div id="cwVerifyError" class="cw-error" role="alert"></div></div><div class="modalfoot"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">${action==='Verified'?'Verify Achievement':'Return Goal'}</button></div></form>`,'')}
function cwConfirmVerification(id,cycle,action,form){const g=data.goals.find(g=>String(g.id)===String(id)),c=urCycle(cycle);if(!cwCanManageVerification(g,c)||!['Verified','Returned'].includes(action))return;const reason=String(new FormData(form).get('reason')||'').trim();if(action==='Returned'&&!reason||action==='Verified'&&(cwGoalActual(g,c)==null||!Number.isFinite(Number(cwGoalActual(g,c))))){$('#cwVerifyError').textContent=action==='Returned'?'Enter a reason for revision.':'The employee must record an actual result before verification.';return}cwVerificationEvent(g,c,action,reason);urAudit('Goal '+action.toLowerCase()+': '+g.id+' / '+c.id);closeModal();render();toast(action==='Verified'?'Goal achievement verified':'Goal returned with a reason')}
function cwGoalRows(c,id){return cwLinks(c,id).map(link=>{const g=cwGoal(link),valid=cwAssigned(g,id);return {...urClone(link),name:valid?g.name:'Goal unavailable or reassigned',progress:valid?g.progress:0,due:valid?g.due:'',actual:valid?cwGoalActual(g,c):null,verification:valid?cwVerification(g,c):'Configuration changed',reason:valid?g.goalVerifications?.[c.id]?.reason||'':''}})}
function cwGoalsScore(c,id){if(!c.components.goals||c.scoring.goals!=='manager-verified')return null;const rows=cwGoalRows(c,id);if(!rows.length||rows.some(r=>r.verification!=='Verified'||r.actual==null))return null;const weights=rows.reduce((sum,r)=>sum+r.weight,0);return rows.reduce((sum,r)=>sum+pdIndicatorScore(r,r.actual)*r.weight,0)/weights}
function cwGoalsPanel(c,id,readOnly=false,rows=cwGoalRows(c,id)){return `<section class="panel cw-goal-results"><div class="panelhead"><div><h2>Goals Performance</h2><p>Actual goals linked from the Goals module · ${esc(c.goalTemplateSnapshots?.[id]?.name||cwGoalTemplate(c,id)?.name||'')}</p></div></div><div class="tablewrap"><table><thead><tr><th>ASSIGNED GOAL</th><th>TARGET</th><th>PROGRESS</th><th>RECORDED ACTUAL</th><th>VERIFICATION</th><th>REVIEW</th></tr></thead><tbody>${rows.map(r=>{const g=cwGoal(r);return `<tr><td><b>${esc(r.name)}</b><small>${r.due?date(r.due):''}</small></td><td>${r.direction==='Lower'?'Maximum ':''}${r.target} ${esc(r.unit)}</td><td>${progress(r.progress)}</td><td>${r.actual??'Not recorded'}</td><td>${urBadge(r.verification)}${r.reason?`<small>${esc(r.reason)}</small>`:''}</td><td>${!readOnly&&g&&pmsGoalInScope(g)?`<button class="textbtn" onclick="pmsViewGoal(${JSON.stringify(r.goalId)})">View Goal</button>`:''}${!readOnly&&g&&cwCanRecord(g,c)?`<button class="textbtn" onclick="cwRecordActual('${g.id}','${c.id}')">${Number(g.progress)===100?'Submit for Verification':'Record Actual'}</button>`:''}${!readOnly&&g&&cwCanManageVerification(g,c)?`<button class="textbtn" onclick="cwVerifyGoal('${g.id}','${c.id}','Verified')">Verify Achievement</button><button class="textbtn" onclick="cwVerifyGoal('${g.id}','${c.id}','Returned')">Return for Revision</button>`:''}${readOnly?`${urRating(r.verification==='Verified'?pdIndicatorScore(r,r.actual):null)}`:''}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No linked assigned goals.</td></tr>'}</tbody></table></div><p class="pd-score-note">Progress and milestone updates do not require approval. A 100% goal is complete in progress only; verified actuals determine evaluation scoring.</p></section>`}
pmsViewGoal=function(id){cwBase.viewGoal(id);const g=data.goals.find(g=>String(g.id)===String(id));if(!g||!pmsGoalInScope(g))return;const cycles=UR.cycles.filter(c=>(cwV2(c)||c.demoGoalMigration)&&c.components.goals&&cwLinks(c,pmsGoalOwner(g)).some(l=>String(l.goalId)===String(g.id))&&(urHr()||viewRole==='Manager'&&urTeam(pmsGoalOwner(g))||pmsGoalOwner(g)===urUser()));const body=$('#modal .modalbody');if(body&&cycles.length)body.insertAdjacentHTML('beforeend',`<section class="cw-goal-verification"><h3>Evaluation Goal Verification</h3>${cycles.map(c=>`<p><b>${esc(c.name)}</b><br>${esc(cwVerification(g,c))}${g.goalVerifications?.[c.id]?.reason?' · '+esc(g.goalVerifications[c.id].reason):''}</p><p class="cw-help">${cwLinks(c,pmsGoalOwner(g)).filter(l=>String(l.goalId)===String(g.id)).map(l=>'Target: '+l.target+' '+esc(l.unit)+' · Actual result: '+(cwGoalActual(g,c)??'Not recorded')).join('')}</p>${cwCanRecord(g,c)?`<button onclick="cwRecordActual('${g.id}','${c.id}')">${Number(g.progress)===100?'Submit for Verification':'Record Actual Result'}</button>`:''}`).join('')}</section>`)};
function cwManagerBlock(a){const c=urCycle(a.cycle);return cwV2(c)&&c.components.goals&&a.type==='Manager'?cwGoalRows(c,a.subject).filter(r=>r.verification!=='Verified').map(r=>`${r.name}: resolve Manager verification (${r.verification}).`):[]}
function cwResponseErrors(a){const errors=cwManagerBlock(a);for(const q of a.template.questions){const raw=urAnswers[q.id];if(q.required&&!String(raw??'').trim())errors.push('Answer '+q.title+'.');if(raw&&q.type==='Rating'&&!((raw==='NO'&&q.notObserved)||[1,2,3,4,5].includes(Number(raw))))errors.push('Choose a valid rating for '+q.title+'.');if(raw&&q.type==='Choice'&&!q.options.includes(raw))errors.push('Choose a valid option for '+q.title+'.')}return errors}
urReviewDetail=function(){const a=UR.assignments.find(x=>x.id===urDetail),c=a&&urCycle(a.cycle);if(!cwV2(c))return cwBase.detail();if(!urVisible(a)||!urCanRead(a))return urEmpty('Review unavailable','This assignment is outside your scope.');const editable=urCanEdit(a),stage=c.stages.find(s=>s.id===a.stage);return pdBack("urGoTab('Reviews')",'Back to Reviews')+pdHead('Assessment Details',urPerson(a.subject).name+' · '+stage.name,c.released&&urCanResult(c,a.subject)?`<button class="primary" onclick="urOpenResult('${c.id}','${a.subject}')">View Employee Evaluation Results</button>`:'')+`<section class="panel pd-form">${pdStageTimeline(c,a.subject)}</section>${!pdUnlocked(a)?cwNotice('Locked — Awaiting Previous Assessment. No future-stage responses are editable.'):cwNotice(`${editable?'Complete your assigned stage.':'This submitted assessment is read-only.'} Due ${date(a.deadline)} · ${urEffective(a)}`)+(c.components.goals?cwGoalsPanel(c,a.subject):'')+(c.components.behavioral?`<section class="panel pd-form"><h2>Behavioral Performance</h2><p>${esc(a.template.name)} · v${a.template.version}</p>${urQuestionFields(a.template,urAnswers,!editable)}</section>`:'')+`<section class="panel pd-form"><label>Written Feedback<textarea rows="4" ${editable?'':'readonly'} oninput="pdFeedback=this.value;urDirty=true">${esc(editable?pdFeedback:a.feedback||'')}</textarea></label></section>${editable?`<div class="urerror" id="urValidation" role="alert"></div><div class="pd-form-footer"><button onclick="urSaveResponse()">Save Draft</button><button class="primary" onclick="urConfirmSubmit()">Submit Assessment</button></div>`:''}`}`};
urSaveResponse=function(){const a=UR.assignments.find(x=>x.id===urDetail),c=a&&urCycle(a.cycle);if(!cwV2(c))return cwBase.save();if(!urCanEdit(a))return;a.answers=urClone(urAnswers);a.feedback=pdFeedback.trim();a.state='In Progress';a.updated=pdDate();urDirty=false;urAudit('Connected assessment draft saved: '+a.id);render();toast('Assessment draft saved')};
urConfirmSubmit=function(){const a=UR.assignments.find(x=>x.id===urDetail),c=a&&urCycle(a.cycle);if(!cwV2(c))return cwBase.confirm();if(!urCanEdit(a))return;const errors=cwResponseErrors(a);if(errors.length){$('#urValidation').textContent=errors.join(' ');$('#urValidation').scrollIntoView({block:'center'});return}modal('Submit Assessment?','',`<div class="modalbody"><p>This stage becomes read-only and unlocks the next eligible stage. Shared goals are not duplicated. Results require HR finalization and explicit release.</p></div>`,`<button onclick="closeModal()">Keep Editing</button><button class="primary" onclick="urSubmitResponse()">Submit Assessment</button>`)};
urSubmitResponse=function(){const a=UR.assignments.find(x=>x.id===urDetail),c=a&&urCycle(a.cycle);if(!cwV2(c))return cwBase.submit();if(!urCanEdit(a)||cwResponseErrors(a).length)return;a.answers=urClone(urAnswers);a.feedback=pdFeedback.trim();a.state='Submitted';a.submitted=pdDate();a.updated=pdDate();urDirty=false;urAudit('Connected assessment submitted: '+a.id);closeModal();render();toast('Assessment submitted; next stage is available')};
function cwBehaviorScore(c,id){if(!c.components.behavioral||!c.scoring.behavioral)return null;const rows=pdStageRows(c,id).filter(a=>['Submitted','Completed'].includes(a.state)&&!urAnon(a)&&(c.scoring.behavioral==='average'||a.type===c.scoring.behavioral));const ratings=rows.flatMap(a=>a.template.questions.filter(q=>q.type==='Rating').map(q=>a.answers[q.id]).filter(v=>v&&v!=='NO').map(Number)).filter(v=>Number.isFinite(v)&&v>=1&&v<=5);return urAvg(ratings)}
pdDimensionResults=function(c,id){if(!cwV2(c))return cwBase.dimensions(c,id);const fixed=c.resultSnapshots?.[id],rows=pdStageRows(c,id).filter(a=>['Submitted','Completed'].includes(a.state)&&!urAnon(a));return {rows,goalRows:fixed?.goals||cwGoalRows(c,id),goalScore:fixed?fixed.goalScore:cwGoalsScore(c,id),behaviorScore:fixed?fixed.behaviorScore:cwBehaviorScore(c,id)}};
urMean=function(a){const c=urCycle(a.cycle);if(!cwV2(c))return cwBase.mean(a);if(c.status!=='Completed')return null;const r=pdDimensionResults(c,a.subject);return pdWeighted(r.goalScore,r.behaviorScore,cwWeights(c))};
function cwFinalizeErrors(c){return c.components.goals?c.participants.flatMap(id=>cwGoalRows(c,id).filter(r=>r.verification!=='Verified').map(r=>`${urPerson(id).name}: ${r.name} requires current Manager verification.`)):[]}
urFinalizeCycle=function(id){const c=urCycle(id);if(cwV2(c)&&cwFinalizeErrors(c).length){toast(cwFinalizeErrors(c)[0]);return}cwBase.askFinalize(id)};
urDoFinalize=function(id){const c=urCycle(id);if(cwV2(c)){const assignments=urCycleAssignments(c);if(!urHr()||c.status!=='Active'||!assignments.length||assignments.some(a=>!['Submitted','Completed'].includes(a.state))||cwFinalizeErrors(c).length)return;c.resultSnapshots=Object.fromEntries(c.participants.map(subject=>[subject,{goals:cwGoalRows(c,subject),goalScore:cwGoalsScore(c,subject),behaviorScore:cwBehaviorScore(c,subject),scoring:urClone(c.scoring),weights:cwWeights(c),at:pdNow()}]))}cwBase.finalize(id)};
urEmployeeResults=function(){const c=urCycle(urResultCycle),subject=urResultSubject;if(!cwV2(c))return cwBase.results();if(!urCanResult(c,subject))return urEmpty('Results unavailable','HR has not released results to your role.');const p=urPerson(subject),r=pdDimensionResults(c,subject),weights=cwWeights(c),overall=pdWeighted(r.goalScore,r.behaviorScore,weights);return pdBack("urGoTab('Reviews')",'Back to Reviews')+pdHead('Employee Evaluation Results',p.name+' · '+c.name)+`<section class="panel pd-form"><div class="cw-summary-pairs">${[['Employee',p.name],['Position',p.position],['Department',p.department],['Evaluation Period',date(c.periodStart)+' – '+date(c.periodEnd)],['Completion',c.status],['Results','Released']].map(([k,v])=>`<div><small>${k}</small><b>${esc(v)}</b></div>`).join('')}</div></section><section class="panel pd-form"><h2>Assessment Stage Summary</h2>${pdStageTimeline(c,subject)}</section>${c.components.goals?cwGoalsPanel(c,subject,true,r.goalRows):''}${c.components.behavioral?`<section class="panel pd-form"><h2>Behavioral Performance Results</h2>${r.rows.map(a=>`<p><b>${esc(c.stages.find(s=>s.id===a.stage).name)}</b> · ${urRating(pdOld.mean(a))}</p>`).join('')}<p>Aggregation: ${esc(cwPolicyLabel(c))}. Unanswered and Not Observed ratings are excluded; written answers are not scored.</p></section>`:''}<section class="panel pd-form"><h2>Overall Performance Summary</h2><div class="pd-result-scores">${c.components.goals?`<div><small>Goals Performance · ${weights.goals}%</small><strong>${urRating(r.goalScore)}</strong></div>`:''}${c.components.behavioral?`<div><small>Behavioral Performance · ${weights.behavioral}%</small><strong>${urRating(r.behaviorScore)}</strong></div>`:''}<div><small>Overall Performance</small><strong>${urRating(overall)}</strong></div></div><p>Cycle policy: ${c.components.goals?'Manager-verified goal actuals. ':''}${c.components.behavioral?esc(cwPolicyLabel(c)):''} These are configured cycle policies, not a universal HR rule.</p></section><section class="panel pd-form"><h2>Written Feedback</h2>${r.rows.filter(a=>a.feedback).map(a=>`<blockquote><b>${esc(c.stages.find(s=>s.id===a.stage).name)}</b><p>${esc(a.feedback)}</p></blockquote>`).join('')||'<p>No written feedback recorded.</p>'}</section>${pdCanJournal(subject)?`<section class="panel pd-form"><h2>Supporting Performance Records</h2><button onclick="pdOpenJournal('${subject}')">View 202 File</button></section>`:''}`};
urCycleDetail=function(){const html=cwBase.cycleDetail(),c=urCycle(urDetail);if(!cwV2(c)||urDetailTab!=='Overview')return html;return html+`<section class="panel pd-form"><h2>Connected Evaluation Configuration</h2><p>Goals Performance: ${c.components.goals?'Enabled':'Disabled'} · Behavioral Performance: ${c.components.behavioral?'Enabled':'Disabled'}</p><p>Goals policy: ${c.scoring.goals==='manager-verified'?'Manager-verified actuals':'Not applicable'}. Behavioral policy: ${esc(cwPolicyLabel(c))}.</p>${cwReadiness(c,false)}</section>`};
function cwSeed(){
 if(UR.connectedGoalWorkflowVersion)return;
 const indicators=[pdIndicator('Timely Completion of Design Deliverables','Percentage',95),pdIndicator('Accurate Design Documentation','Percentage',98),pdIndicator('Developer Handoff Completion','Percentage',100)];indicators.forEach((x,i)=>x.weight=[34,33,33][i]);
 const template={id:'cw-product-designer-goals',name:'Product Designer Performance Goals',description:'Standard performance expectations for Product Designers.',position:'Product Designer',status:'Published',version:1,updated:pdDate(),indicators};UR.goalTemplates.push(template);
 const c=cwLegacyCycle();Object.assign(c,{id:'cw-design-2026',name:'Annual Performance Review 2026 — Design',description:'Evaluate design delivery, documentation, developer handoff, and workplace behaviors.',participants:['EMP-001'],behavioralTemplate:'pd-behaviors',scoring:{goals:'manager-verified',behavioral:'average'},sample:true});c.goalTemplates['EMP-001']=template.id;c.goalLinks['EMP-001']=[];
 indicators.forEach((x,i)=>{const g={id:pmsGoalId(),name:x.name,description:'Assigned from Product Designer Performance Goals for the 2026 Design evaluation.',employee:'Maria Cruz',ownerId:'EMP-001',createdBy:'HR-001',createdByName:urPerson('HR-001').name,createdAt:pdNow(),assignedBy:urPerson('HR-001').name,source:'assigned',category:'Quality',startDate:'2026-01-01',due:'2026-10-30',cycle:c.id,evaluationCycles:[c.id],progress:[100,67,100][i],trackingMode:'manual',milestones:[],status:i===1?'Active':'Completed',updates:[]};data.goals.push(g);c.goalLinks['EMP-001'].push({goalId:g.id,indicatorId:x.id,target:x.target,unit:x.unit,direction:x.direction,weight:x.weight,scoreMet:x.scoreMet,scoreBelow:x.scoreBelow,requiresVerification:true})});UR.cycles.push(c);UR.connectedGoalWorkflowVersion=1;save();
}
cwSeed();
const cwRender=render;
function cwRestoreDraftListing(){const draft=UR.draftCycle;if(!draft?.id||draft.status&&draft.status!=='Draft'||UR.cycles.some(c=>c.id===draft.id))return;UR.cycles.push({...urClone(draft),status:'Draft',name:draft.name?.trim()||'Untitled review cycle'});urPersist()}
cwRestoreDraftListing();
const cwSaveDraft=urSaveCycleDraft;
urSaveCycleDraft=function(){if(cwV2(urWizard)){urWizard.deadline=urWizard.stages.at(-1)?.deadline||'';if(urWizard.setupVersion===3)urWizard.savedStep=Math.max(1,Math.min(5,urStep))}cwSaveDraft()};
render=function(){cwRender();if(page==='Reviews'&&urScreen==='wizard'&&cwV2(urWizard)&&urStep===2)cwDrawParticipants()};
for(const c of UR.cycles.filter(c=>cwV2(c)&&c.status==='Scheduled'&&c.start<=urToday&&c.deadline>=urToday)){c.status='Active';cwGenerate(c);urAudit('Connected scheduled cycle opened: '+c.id)}
render();
